## How Reconciliation Works

```jsx
// Before state update
<ul>
  <li key="a">Apple</li>
  <li key="b">Banana</li>
</ul>

// After state update — item added at beginning
<ul>
  <li key="c">Cherry</li>  {/* new */}
  <li key="a">Apple</li>   {/* moved, same key = reuse */}
  <li key="b">Banana</li>  {/* moved, same key = reuse */}
</ul>
```

With keys, React knows `a` and `b` are unchanged — only inserts `c`. Without keys, it sees index 0 changed from `Apple` to `Cherry`, index 1 changed from `Banana` to `Apple`, and index 2 is new — causing 3 DOM operations instead of 1.

## The Keys Anti-Pattern

```jsx
// BAD — index as key causes issues when items are reordered or removed
{items.map((item, index) => (
  <Item key={index} data={item} />
))}

// GOOD — stable, unique ID as key
{items.map(item => (
  <Item key={item.id} data={item} />
))}
```

Using index as key is fine only for static lists that never change order.

## React Fiber (React 16+)

Fiber is React's reconciliation engine — a complete rewrite. It turns reconciliation into an interruptible, prioritized work loop instead of a synchronous stack walk. High-priority updates (user input) can interrupt low-priority ones (data loading). This is what makes Concurrent Mode and features like `useTransition` possible.

```jsx
import { useTransition, useState } from 'react';

function Search() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [isPending, startTransition] = useTransition();

  const handleChange = (e) => {
    setQuery(e.target.value);  // Immediate — high priority

    startTransition(() => {
      // Deferred — can be interrupted by user typing
      setResults(filterResults(e.target.value));
    });
  };

  return (
    <>
      <input value={query} onChange={handleChange} />
      {isPending ? <Spinner /> : <ResultList results={results} />}
    </>
  );
}
```

## The Linked List Model

```jsx
function Counter() {
  // Render 1: Hook slot 0 = count(0), slot 1 = name('')
  const [count, setCount] = useState(0);  // slot 0
  const [name, setName] = useState('');   // slot 1
}

// React stores: [{ state: 0, next: → }, { state: '', next: null }]
// On re-render, reads slot 0 → 0, slot 1 → ''
```

## What Breaks With Conditional Hooks

```jsx
// BAD — hook order changes when isLoggedIn changes
function Profile({ isLoggedIn }) {
  if (isLoggedIn) {
    const [username, setUsername] = useState('');  // sometimes slot 0
  }
  const [theme, setTheme] = useState('light');  // sometimes slot 0, sometimes slot 1!
}
// When isLoggedIn flips: theme reads username's stored state = corrupted
```

## How To Handle Conditional Logic

```jsx
// GOOD — hook always called, condition inside
function Profile({ isLoggedIn }) {
  const [username, setUsername] = useState('');  // always slot 0
  const [theme, setTheme] = useState('light');   // always slot 1

  useEffect(() => {
    if (isLoggedIn) {          // Condition inside the hook
      fetchUsername().then(setUsername);
    }
  }, [isLoggedIn]);
}

// Or: push the component split above the conditional
function App() {
  return isLoggedIn ? <AuthProfile /> : <GuestProfile />;
}
```

## Custom Hook Pattern

```jsx
// Extract repeated hook logic into a named function
function useUserData(userId) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);

    fetchUser(userId)
      .then(data => { if (!cancelled) { setUser(data); setLoading(false); } })
      .catch(err => { if (!cancelled) { setError(err); setLoading(false); } });

    return () => { cancelled = true; };  // Cleanup on unmount or userId change
  }, [userId]);

  return { user, loading, error };
}

// Usage — clean and reusable
function UserCard({ userId }) {
  const { user, loading, error } = useUserData(userId);
  if (loading) return <Spinner />;
  if (error) return <Error message={error.message} />;
  return <div>{user.name}</div>;
}
```

## Decision Tree

```
Is it server data (API responses)?
  YES → React Query / SWR
  NO → Is it used in just this component?
    YES → useState / useReducer
    NO → Is it updated frequently?
      YES → Zustand / Jotai (avoid Context re-renders)
      NO → Context (auth, theme, language)
```

## React Query — Server State

```jsx
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

function UserList() {
  const { data: users, isLoading, error } = useQuery({
    queryKey: ['users'],
    queryFn: () => fetch('/api/users').then(r => r.json()),
    staleTime: 5 * 60 * 1000,  // Data is fresh for 5 minutes
    gcTime: 10 * 60 * 1000,    // Keep in cache for 10 minutes
  });

  const queryClient = useQueryClient();
  const deleteMutation = useMutation({
    mutationFn: (userId) => fetch(`/api/users/${userId}`, { method: 'DELETE' }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['users'] }),
  });

  if (isLoading) return <Spinner />;
  if (error) return <Error />;

  return users.map(user => (
    <div key={user.id}>
      {user.name}
      <button onClick={() => deleteMutation.mutate(user.id)}>Delete</button>
    </div>
  ));
}
```

## Zustand — Client State

```jsx
import { create } from 'zustand';

const useCartStore = create((set, get) => ({
  items: [],
  total: 0,

  addItem: (item) => set(state => ({
    items: [...state.items, item],
    total: state.total + item.price,
  })),

  removeItem: (id) => set(state => {
    const items = state.items.filter(i => i.id !== id);
    return { items, total: items.reduce((s, i) => s + i.price, 0) };
  }),
}));

// Usage — only re-renders when cart changes
function CartBadge() {
  const count = useCartStore(state => state.items.length);  // Selector
  return <span>{count}</span>;
}
```

## Context Anti-Pattern (Context Re-render Storm)

```jsx
// BAD — every context update re-renders ALL consumers
const AppContext = createContext();
function App() {
  const [user, setUser] = useState(null);
  const [theme, setTheme] = useState('light');
  const [cart, setCart] = useState([]);  // Updating cart re-renders EVERYTHING

  return (
    <AppContext.Provider value={{ user, theme, cart, setCart }}>
      ...
    </AppContext.Provider>
  );
}

// GOOD — separate contexts, each only re-renders its consumers
<UserContext.Provider value={user}>
  <ThemeContext.Provider value={theme}>
    <CartContext.Provider value={{ cart, setCart }}>
      ...
    </CartContext.Provider>
  </ThemeContext.Provider>
</UserContext.Provider>
```
